head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 0. 엔진내부 WEB-INF 폴더하위에 있는 web.xml 을 열어서 내용을 추가한다. 
    //Open the web.xml under the engine"s WEB-INF folder and add the contents.
    // verify step 0. 코멘트참고 
    //0. Comment Reference
    // Test step 1. 브라우저에서 확인한다. 
    //1. Check in the browser.
    // verify step 1. 정상적으로 화면이 표시된다. (그전버전에서는 그림1처럼 에러메세지가 뜨면서 화면이 표시되지 않음)기타. IE 브라우저에서는 재현하기 힘듬
    //1. The screen is displayed normally. (In the previous version, the error message appears as shown in Figure 1, and the screen is not displayed.)Etc. In IE browser is difficult to reproduce
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'textbox1').innerText", "Websquare is working successfully");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 25-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
